import ts from 'typescript';
import { readFileSync, writeFileSync } from 'node:fs';

// Compile the same pure preference functions Angular uses; do not maintain a second parser.
const source = readFileSync(new URL('../src/app/colour-mode-preferences.ts', import.meta.url), 'utf8');
const { outputText } = ts.transpileModule(source, {
  compilerOptions: { target: ts.ScriptTarget.ES2018, module: ts.ModuleKind.CommonJS, removeComments: true },
});
writeFileSync(new URL('../public/colour-mode-init.js', import.meta.url),
  '/* Generated by scripts/build-colour-bootstrap.mjs. Edit colour-mode-preferences.ts. */\n' +
  '(function () { const exports = {};\n' + outputText + '\nexports.restoreColourMode();\n' +
  'document.addEventListener("DOMContentLoaded", function () {\n' +
  '  const meta = document.querySelector("meta[name=theme-color]");\n' +
  '  if (meta) meta.content = getComputedStyle(document.documentElement).getPropertyValue("--background").trim();\n' +
  '}, { once: true });\n})();\n');
